const body = $('Availability Webhook').first().json.body ?? {};

function normalizeDate(value) {
  const text = String(value ?? '').trim();

  // YYYY-MM-DD
  let match = text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (match) {
    return `${match[1]}-${match[2].padStart(2, '0')}-${match[3].padStart(2, '0')}`;
  }

  // M/D/YYYY
  match = text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (match) {
    return `${match[3]}-${match[1].padStart(2, '0')}-${match[2].padStart(2, '0')}`;
  }

  return text;
}

function normalizeTime(value) {
  const text = String(value ?? '').trim().toUpperCase();

  // Supports 19:30, 7:30 PM, 7 PM
  const match = text.match(/^(\d{1,2})(?::(\d{2}))?\s*(AM|PM)?$/);

  if (!match) {
    return text;
  }

  let hour = Number(match[1]);
  const minute = Number(match[2] ?? 0);
  const period = match[3];

  if (period === 'AM' && hour === 12) {
    hour = 0;
  } else if (period === 'PM' && hour !== 12) {
    hour += 12;
  }

  return `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;
}

const requestedDate = normalizeDate(body.date);
const requestedTime = normalizeTime(body.time);
const partySize = Number.parseInt(body.party_size, 10);

const CAPACITY = 40;

if (!requestedDate || !requestedTime) {
  throw new Error('Reservation date and time are required.');
}

if (!Number.isInteger(partySize) || partySize < 1) {
  throw new Error('Party size must be a positive whole number.');
}

const rows = $input.all().map(item => item.json);

const matchingReservations = rows.filter(row => {
  const rowDate = normalizeDate(row.reservation_date);
  const rowTime = normalizeTime(row.reservation_time);
  const status = String(row.status ?? 'active').trim().toLowerCase();

  return (
    rowDate === requestedDate &&
    rowTime === requestedTime &&
    status !== 'cancelled'
  );
});

const bookedCount = matchingReservations.reduce((total, row) => {
  const existingPartySize = Number.parseInt(row.party_size, 10);
  return total + (Number.isInteger(existingPartySize) ? existingPartySize : 0);
}, 0);

const remainingCapacity = Math.max(CAPACITY - bookedCount, 0);
const available = partySize <= remainingCapacity;

return [
  {
    json: {
      available,
      booked_count: bookedCount,
      requested_party_size: partySize,
      remaining_capacity: remainingCapacity,
      capacity: CAPACITY,
      date: requestedDate,
      time: requestedTime
    }
  }
];

const body =
  $('Manage Reservation Webhook').first().json.body ?? {};

function normalizePhone(value) {
  const digits = String(value ?? '').replace(/\D/g, '');

  // Compare the final 10 digits so 0349... and +92349... both match.
  return digits.length > 10 ? digits.slice(-10) : digits;
}

function normalizeDate(value) {
  const text = String(value ?? '').trim();

  // Already in YYYY-MM-DD format
  let match = text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);

  if (match) {
    return `${match[1]}-${match[2].padStart(2, '0')}-${match[3].padStart(2, '0')}`;
  }

  // Convert M/D/YYYY to YYYY-MM-DD
  match = text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);

  if (match) {
    return `${match[3]}-${match[1].padStart(2, '0')}-${match[2].padStart(2, '0')}`;
  }

  return text;
}

const phone = normalizePhone(body.phone_number);
const date = normalizeDate(body.date);

if (!phone || !date) {
  return [{
    json: {
      found: false,
      error: 'phone_number or date is missing',
    },
  }];
}

const rows = $input.all();

const match = rows.find(({ json }) => {
  const rowPhone = normalizePhone(json.phone_number);
  const rowDate = normalizeDate(json.reservation_date);
  const status = String(json.status ?? '').trim().toLowerCase();

  return (
    rowPhone === phone &&
    rowDate === date &&
    status !== 'cancelled'
  );
});

if (!match) {
  return [{
    json: {
      found: false,
      searched_phone: phone,
      searched_date: date,
    },
  }];
}

return [{
  json: {
    ...match.json,
    found: true,
    row_number: match.json.row_number,
  },
}];

const body = $('Manage Reservation Webhook').first().json.body ?? {};
const original = $input.first().json;

function hasValue(v) {
  return v !== undefined && v !== null && String(v).trim() !== '';
}

return [
  {
    json: {
      row_number: original.row_number,
      reservation_date: hasValue(body.new_date) ? body.new_date : original.reservation_date,
      reservation_time: hasValue(body.new_time) ? body.new_time : original.reservation_time,
      party_size: hasValue(body.new_party_size) ? body.new_party_size : original.party_size
    }
  }
];
